:scope {
  --ink: #2C3E50;
  --muted: #7F8C8D;
  --accent: #00B894;
  --warm: #E17055;
  --paper: #F5F5F7;
  --line: #DFE6E9;
  --font-base: 16px;
  --font-sm: 14px;
  --radius: 8px;
  --shadow: 0 4px 12px rgba(0,0,0,0.05);

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
  padding: 2rem;
  box-sizing: border-box;
  display: block;
}

:scope * {
  box-sizing: border-box;
}

.chapter-header h1 {
  font-size: 2rem;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
  font-weight: 700;
}

.chapter-lead {
  font-size: 1.125rem;
  color: var(--muted);
  margin: 0 0 2rem 0;
  max-width: 700px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 2rem;
  margin-bottom: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.info-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: var(--shadow);
  transition: transform 0.2s ease;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.75rem;
}

.card-header h3 {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 600;
}

.tag {
  font-size: 0.75rem;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tag-ideal {
  background: #E3F2FD;
  color: #1565C0;
}

.tag-future {
  background: #E8F5E9;
  color: #2E7D32;
}

.card-body p {
  margin: 0 0 1rem 0;
  font-size: var(--font-base);
  color: #34495E;
}

.card-body p:last-child {
  margin-bottom: 0;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.8rem;
  padding: 0.1rem 0.4rem;
  border-radius: 4px;
  cursor: pointer;
  vertical-align: middle;
  margin-left: 0.25rem;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--ink);
  color: var(--ink);
  background: #fff;
}

.viz-container {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1rem;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.viz-controls {
  display: flex;
  gap: 0.5rem;
}

.control-btn {
  flex: 1;
  padding: 0.6rem;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--muted);
  font-size: 0.9rem;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.control-btn.active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 4/3;
  background: #FAFAFA;
  border-radius: 4px;
  overflow: hidden;
  border: 1px solid var(--line);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.viz-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(44, 62, 80, 0.9);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
  padding: 1.5rem;
}

.viz-overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.overlay-content h4 {
  margin: 0 0 1rem 0;
  color: var(--accent);
  font-size: 1.2rem;
}

.overlay-content ul {
  margin: 0;
  padding-left: 1.2rem;
  font-size: 0.95rem;
}

.overlay-content li {
  margin-bottom: 0.5rem;
}

.viz-caption {
  font-size: 0.85rem;
  color: var(--muted);
  text-align: center;
}

.data-support {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.data-support h3 {
  margin: 0 0 0.5rem 0;
  font-size: 1.2rem;
}

.data-intro {
  font-size: 0.95rem;
  color: var(--muted);
  margin: 0 0 1.5rem 0;
}

.table-responsive {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  min-width: 500px;
}

.data-table th, .data-table td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

.data-table th {
  background: #F8F9FA;
  color: var(--ink);
  font-weight: 600;
}

.data-table tr:last-child td {
  border-bottom: none;
}

.table-note {
  margin-top: 1rem;
  font-size: 0.8rem;
  color: var(--muted);
  font-style: italic;
}
@media(max-width:620px){.content-grid,.grid-layout,.interactive-stage{display:block!important}.data-row{flex-wrap:wrap}.formula-card{overflow:auto}canvas{max-width:100%;height:auto}}
.viz-overlay,.viz-overlay.visible{pointer-events:none!important}

