(function() {
  'use strict';

  // --- 数据加载 ---
  const tables = window.paperMindData?.tables || [];
  const rmseTable = tables.find(t => t.id === 'p11-Table_4');
  const tbody = document.getElementById('rmse-table-body');

  if (rmseTable && tbody) {
    rmseTable.rows.forEach(row => {
      const tr = document.createElement('tr');
      // 构造单元格，确保数值正确读取
      const cells = [
        row.values['Method'],
        row.values['ε_φaz (rad)'],
        row.values['ε_φel (rad)'],
        row.values['ε_θaz (rad)'],
        row.values['ε_θel (rad)'],
        row.values['ε_τ (us)']
      ];

      cells.forEach((text, idx) => {
        const td = document.createElement('td');
        td.textContent = text || 'N/A';
        // 高亮自适应方法的低误差
        if (row.label === 'Adaptive DCS-SOMP' && idx > 0) {
          td.style.color = '#00B894';
          td.style.fontWeight = '600';
        }
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
  }

  // --- 可视化逻辑 ---
  const canvas = document.getElementById('limit-canvas');
  const ctx = canvas.getContext('2d');
  const btnIdeal = document.getElementById('btn-ideal');
  const btnReal = document.getElementById('btn-real');
  const overlay = document.getElementById('viz-overlay');

  let state = 'ideal'; // 'ideal' or 'real'
  let animationFrame;

  // 绘图参数
  const colors = {
    bg: '#FAFAFA',
    bs: '#2C3E50',
    ms: '#00B894',
    pathIdeal: '#95A5A6',
    pathReal: '#E17055',
    text: '#2C3E50'
  };

  function draw() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // 背景
    ctx.fillStyle = colors.bg;
    ctx.fillRect(0, 0, w, h);

    // 绘制基站 (BS) 和 移动站 (MS)
    const bsX = 50, bsY = h / 2;
    const msX = w - 50, msY = h / 2;

    // BS
    ctx.fillStyle = colors.bs;
    ctx.beginPath();
    ctx.arc(bsX, bsY, 15, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('BS', bsX, bsY + 4);

    // MS
    ctx.fillStyle = colors.ms;
    ctx.beginPath();
    ctx.arc(msX, msY, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.fillText('MS', msX, msY + 4);

    if (state === 'ideal') {
      // 理想状态：直射 + 单反射
      drawPath(ctx, bsX, bsY, msX, msY, colors.pathIdeal, false);
      drawReflectedPath(ctx, bsX, bsY, msX, msY, colors.pathIdeal);

      ctx.fillStyle = colors.text;
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText('完美同步 / 单反射模型', 20, 30);
    } else {
      // 现实状态：偏差 + 多反射
      drawPath(ctx, bsX, bsY, msX, msY, colors.pathReal, true);
      drawMultiPath(ctx, bsX, bsY, msX, msY, colors.pathReal);

      // 绘制时钟偏差符号
      ctx.strokeStyle = '#E17055';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(msX - 10, msY - 25);
      ctx.lineTo(msX + 10, msY - 25);
      ctx.stroke();
      ctx.fillStyle = '#E17055';
      ctx.font = 'bold 12px sans-serif';
      ctx.fillText('Δt (时钟偏差)', msX, msY - 30);

      ctx.fillStyle = colors.text;
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText('时钟偏差 / 多反射干扰', 20, 30);
    }
  }

  function drawPath(ctx, x1, y1, x2, y2, color, isDashed) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    if (isDashed) ctx.setLineDash([5, 5]);
    else ctx.setLineDash([]);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    // 添加一点随机扰动模拟现实
    if (state === 'real') {
      ctx.quadraticCurveTo((x1+x2)/2, y1 + 20, x2, y2);
    } else {
      ctx.lineTo(x2, y2);
    }
    ctx.stroke();
    ctx.setLineDash([]);
  }

  function drawReflectedPath(ctx, x1, y1, x2, y2, color) {
    const midX = (x1 + x2) / 2;
    const reflectY = 40; // 天花板反射

    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(midX, reflectY);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  function drawMultiPath(ctx, x1, y1, x2, y2, color) {
 const h=canvas.height;
    // 绘制几条杂乱的反射路径
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.setLineDash([2, 3]);
    ctx.globalAlpha = 0.6;

    const paths = [
      {y: 60}, {y: h - 60}, {y: h/2 + 40}
    ];

    paths.forEach(p => {
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.quadraticCurveTo((x1+x2)/2, p.y, x2, y2);
      ctx.stroke();
    });

    ctx.globalAlpha = 1.0;
    ctx.setLineDash([]);
  }

  // 交互事件
  btnIdeal.addEventListener('click', () => {
    state = 'ideal';
    btnIdeal.classList.add('active');
    btnReal.classList.remove('active');
    overlay.classList.remove('visible');
    draw();
  });

  btnReal.addEventListener('click', () => {
    state = 'real';
    btnReal.classList.add('active');
    btnIdeal.classList.remove('active');
    overlay.classList.add('visible');
    draw();
  });

  // 初始化
  draw();

  // 来源按钮处理 (由宿主拦截 data-source)
  document.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      // 默认行为由宿主通过 data-source 属性处理
      // 此处仅防止表单提交等默认行为
      e.preventDefault();
    });
  });

})();
